#!/usr/bin/env bash
# Update 82: (1) QR на фактурах/корректах -> https://apstudiomobile.pl/finars/ (тот же стиль, логотип FA);
#  (2) экран подписки: когда Pro активен — без дубля текста над кнопкой, на кнопке две строки
#      ("Pro активирован" / "Спасибо за поддержку!"), корона чуть правее от края;
#  (3) окно замка Склада: убрана фраза про бесплатный пробный период (4 языка).
# Запускать из КОРНЯ репозитория, ДО git add/commit/push. Скрипт идемпотентный.
set -euo pipefail

J=app/src/main/java/com/example/fa_ksiegowy
R=app/src/main/res
for f in "$J/SettingsProActivity.kt" "$R/drawable/qr_download.png" \
         "$R/values/strings.xml" "$R/values-pl/strings.xml" "$R/values-ru/strings.xml" "$R/values-uk/strings.xml"; do
  [ -f "$f" ] || { echo "Запусти из корня репозитория (нет $f)"; exit 1; }
done

B=".update82_backup_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$B/$J" "$B/$R/drawable"
cp "$J/SettingsProActivity.kt" "$B/$J/"
cp "$R/drawable/qr_download.png" "$B/$R/drawable/"
for l in values values-pl values-ru values-uk; do mkdir -p "$B/$R/$l"; cp "$R/$l/strings.xml" "$B/$R/$l/"; done

