# ------------------------------------------------- 2) и 3) Kotlin + строки
python3 - <<'PY'
J = "app/src/main/java/com/example/fa_ksiegowy"
R = "app/src/main/res"
def read(p): return open(p, encoding="utf-8").read()
def write(p, s):
    open(p, "w", encoding="utf-8").write(s); print("изменён:", p)
def rep(s, old, new, what):
    assert s.count(old) == 1, "не найден (или не уникален) фрагмент: " + what
    return s.replace(old, new)

# --- SettingsProActivity.kt
p = J + "/SettingsProActivity.kt"
s = read(p)
if "Update 82" in s:
    print("SettingsProActivity: уже применено")
else:
    s = rep(s,
        "            tvStatus.text = getString(R.string.pro_status_active)\n"
        "            tvStatus.visibility = View.VISIBLE\n",
        "            // Update 82: верхний дубль текста убран — статус виден только на самой кнопке.\n"
        "            tvStatus.visibility = View.GONE\n", "tvStatus Pro")
    s = rep(s,
        "            tvCta.text = getString(R.string.pro_status_active)\n",
        "            // Update 82: две строки по центру; корона отодвинута от края кнопки.\n"
        "            tvCta.text = getString(R.string.pro_cta_active_title) + \"\\n\" + getString(R.string.pro_cta_active_sub)\n"
        "            tvCta.textSize = 14f\n"
        "            tvCta.gravity = android.view.Gravity.CENTER\n"
        "            tvCta.textAlignment = View.TEXT_ALIGNMENT_CENTER\n"
        "            (tvCta.parent as View).setPadding((14 * resources.displayMetrics.density).toInt(), 0, (14 * resources.displayMetrics.density).toInt(), 0)\n",
        "tvCta Pro")
    s = rep(s,
        "            tvCta.text = getString(R.string.paywall_cta, zeroPriceText())\n            applySelectionState()\n",
        "            tvCta.text = getString(R.string.paywall_cta, zeroPriceText())\n"
        "            tvCta.textSize = 17f\n"
        "            (tvCta.parent as View).setPadding(0, 0, 0, 0)\n"
        "            applySelectionState()\n", "tvCta non-Pro")
    write(p, s)

# --- strings
new_cta = {
 "values":    ("Pro activated", "Thank you for your support!"),
 "values-pl": ("Pro odblokowane", "Dziękujemy za wsparcie!"),
 "values-ru": ("Pro активирован", "Спасибо за поддержку!"),
 "values-uk": ("Pro розблоковано", "Дякуємо за підтримку!"),
}
trial = {
 "values":    " Start your free trial.",
 "values-pl": " Rozpocznij bezpłatny okres próbny.",
 "values-ru": " Начните бесплатный пробный период.",
 "values-uk": " Почніть безкоштовний пробний період.",
}
import re
for l in new_cta:
    p = R + "/" + l + "/strings.xml"
    s = read(p); ch = False
    if "pro_cta_active_title" not in s:
        m = re.search(r'^(\s*)<string name="pro_status_active">.*</string>\n', s, re.M)
        assert m, "нет pro_status_active в " + l
        t, sub = new_cta[l]
        add = (m.group(1) + '<string name="pro_cta_active_title">' + t + '</string>\n' +
               m.group(1) + '<string name="pro_cta_active_sub">' + sub + '</string>\n')
        s = s[:m.end()] + add + s[m.end():]; ch = True
    pat = re.compile(r'(<string name="magazin_locked_message">[^<]*?)' + re.escape(trial[l]) + r'(</string>)')
    if pat.search(s):
        s = pat.sub(r'\1\2', s); ch = True
    assert trial[l] not in s.split('name="magazin_locked_message"')[1].split("</string>")[0], "фраза осталась в " + l
    if ch: write(p, s)
    else: print(p, ": уже применено")
PY

